mapper.select:
SELECT m.id AS id, m.room_id AS roomId, m.session_id AS sessionId, m.user_id AS userId, u.`name` AS userName, u.avatar_url AS avatarUrl, m.content AS content, m.create_time AS createTime FROM live_message m INNER JOIN `user` u ON u.id = m.user_id WHERE m.room_id = #{roomId} AND m.status = 1
AND m.id < #{lastId}
ORDER BY m.id DESC LIMIT #{size}
